  "noticeText": "Cook izmanto pārlūka krātuvi jūsu izmantotajām gatavošanas un pierakstīšanās funkcijām. Reklāmas vai analītikas krātuve netiek pievienota.",
  "noticeClose": "Aizvērt paziņojumu par krātuvi",
  "privDraftLabel": "Melnraksts — atjaunināts 2026. gada 28. oktobrī.",
  "privDraft": "Konta funkcijas pašlaik tiek testētas. Tālāk norādītā informācija par pārzini un pakalpojumiem jāaizpilda pirms publiskās palaišanas.",
  "privWho1": "Cook pārzinis ir [pārziņa juridiskais nosaukums un pasta adrese]. Ar jautājumiem un pieprasījumiem par privātumu sazinieties: [privātuma e-pasta adrese]. Šī informācija jāaizpilda, pirms tiek atvērta reģistrācija.",
  "privWhat1": "Kad izveidojat kontu, mēs izmantojam jūsu e-pastu, konta identifikatoru, paroles autentifikācijas ierakstus un verifikācijas statusu, lai nodrošinātu un aizsargātu jūsu kontu. Paroles autentifikācijas pakalpojumu sniedzējs apstrādā kā drošus jaucējus; Cook neglabā nolasāmas paroles. Mēs saglabājam virtuves izkārtojumu, izvēlēto valodu, motīvu un mērvienības, lai atjaunotu jūsu iestatījumus visās ierīcēs. Kontam nepieciešams e-pasts un parole; receptes varat pārlūkot arī bez konta.",
  "privWhat2": "Konta un iestatījumu apstrāde ir nepieciešama, lai sniegtu jūsu pieprasīto konta pakalpojumu (VDAR 6. panta 1. punkta b) apakšpunkts). Ierobežotus drošības un ļaunprātīgas izmantošanas novēršanas ierakstus var apstrādāt, pamatojoties uz leģitīmām interesēm (6. panta 1. punkta f) apakšpunkts), ciktāl tas nepieciešams un pēc interešu izvērtēšanas. Verifikācijas un paroles atiestatīšanas e-pasti ir pakalpojuma ziņojumi, nevis mārketings. Konta funkcija nepievieno reklāmu vai analītiku.",
  "privStorage1": "Cook izmanto sessionStorage, lai pārnestu jūsu virtuvi, gatavošanas progresu un izvēles starp lapām tajā pašā cilnē. Kad esat pierakstījies, tajā glabājas arī jūsu autentifikācijas sesija. Pārlūks parasti to notīra, kad cilnes sesija beidzas, taču pārlūka sesijas atjaunošana to var saglabāt. Izrakstoties tiek notīrīti Cook cilnes dati. Paziņojuma par krātuvi aizvēršana tiek saglabāta tikai attiecīgajā cilnē. Cook paša skripti neiestata sīkdatnes. Jūsu mitināšanas vai pakalpojumu sniedzējiem var būt sava drošības apstrāde, kas jādokumentē pirms palaišanas.",
  "privStorage2": "Labi un paziņojuma par krātuvi aizvēršanas poga tikai aizver paziņojumu. Tās neatļauj analītiku, reklāmu vai citu neobligātu izsekošanu. Jebkurai turpmākai nebūtiskai krātuvei pirms tās sākuma būs nepieciešama atsevišķa izvēle, kur atteikšanās un atsaukšana ir tikpat vienkārša.",
  "privOther1": "Pašreizējā recepšu saraksta runas funkcija, izmantojot jūsu IP adresi, pieprasa country.is aptuvenu valsti, lai izvēlētos runas valodu. Ja izmantojat mikrofona atpazīšanu, pārlūks var nosūtīt audio savam runas atpazīšanas pakalpojumu sniedzējam. Sastāvdaļas varat arī ierakstīt. Šie pakalpojumu sniedzēji, to politikas un šo funkciju juridiskais pamats jāpārskata pirms publiskās palaišanas.",
  "privProviders1": "Plānotais kontu pakalpojumu sniedzējs: Supabase (pārvaldīts PostgreSQL un autentifikācija) ar izvēlētu datubāzes reģionu ES. E-pasta pakalpojumu sniedzējs: [pakalpojumu sniedzējs]. Tīmekļa vietnes mitināšana: [pakalpojumu sniedzējs]. Pārzinim jāapstiprina faktiskie pakalpojumu sniedzēji, apstrādes līgumi, apakšapstrādātāji, žurnālu atrašanās vietas un jebkāda datu nosūtīšana ārpus EEZ. ES datubāzes reģions pats par sevi neizslēdz starptautisku nosūtīšanu. Attiecīgā gadījumā jānorāda piemērojamais lēmums par aizsardzības līmeņa pietiekamību vai līgumiskās garantijas un kā saņemt to kopiju.",
  "privRetention1": "Konta iestatījumi tiek glabāti, kamēr jūsu konts ir aktīvs. Dzēšanu varat pieprasīt, izmantojot iepriekš norādīto privātuma kontaktu. Pirms palaišanas pārzinim jānosaka dzēšanas pieprasījumu izskatīšanas kārtība, neverificētu kontu derīguma termiņš un drošības žurnālu un rezerves kopiju glabāšanas termiņi. Dzēstie dati var palikt ierobežotas piekļuves rezerves kopijās līdz dokumentētā glabāšanas termiņa beigām.",
  "privRights1": "Atkarībā no piemērojamajiem nosacījumiem varat pieprasīt piekļuvi, labošanu, dzēšanu, ierobežošanu vai pārnesamību vai iebilst pret apstrādi, kas balstīta uz leģitīmām interesēm. Sazinieties ar iepriekš norādīto pārzini; uz pieprasījumiem parasti atbild viena mēneša laikā, paskaidrojot jebkādu likumīgu termiņa pagarinājumu. Varat iesniegt sūdzību uzraudzības iestādei, tostarp Ungārijas NAIH vietnē naih.hu. Cook neizmanto konta iestatījumus automatizētiem lēmumiem, kas rada juridiskas vai līdzīgi būtiskas sekas.",
