  "Pot filled": "Katls piepildīts",
  "Put it on the stove": "Uzlikt uz plīts",
  "Put the pot on the largest burner, turn it to HIGH and put the lid on (it boils faster).": "Uzliec katlu uz lielākā degļa, ieslēdz to uz HIGH un uzliec vāku (tā vārās ātrāk).",
